// One JSON file: every email id with its labels, plus the mailbox size it was taken against.
const c = $('Config').first().json;
// n8n's Gmail node returns labels as [{id, name}], the raw API as labelIds. Accept both.
const labelsOf = j => j.labelIds ?? (j.labels || []).map(l => l.id);
const messages = $('List All Messages').all().map(i => ({
  id: i.json.id,
  threadId: i.json.threadId,
  labelIds: [...labelsOf(i.json)].sort(),
}));
// Every real mailbox has INBOX/SENT somewhere. No labels at all means the field was misread,
// and a snapshot of nothing would still "verify" against a mailbox read the same wrong way.
if (messages.length && messages.every(m => m.labelIds.length === 0)) {
  throw new Error('No labels found on any message: the label field was not read. Snapshot not saved.');
}
// Label names next to their ids: a restore can then be limited by name ('n8n', 'gdr', ...)
const labelNames = {};
for (const i of $('List All Messages').all()) for (const l of i.json.labels || []) labelNames[l.id] = l.name;
// Email backup: one .eml per message. Files saved earlier plus the ones saved in this run.
const emlFiles = {};
const folderId = $('Create Email Backup Folder').isExecuted
  ? $('Create Email Backup Folder').first().json.id
  : $('Find Email Backup Folder').first().json.id;
for (const i of $('List Saved Emails').all()) if (i.json.name) emlFiles[i.json.name.replace(/\.eml$/, '')] = i.json.id;
if ($('Save Email Chunk').isExecuted) {
  for (const chunk of $('Save Email Chunk').all()) {
    for (const f of chunk.json.saved || []) emlFiles[f.name.replace(/\.eml$/, '')] = f.id;
  }
}
// Too large to fetch automatically: named in the result, not a reason to stop
const MAX_BYTES = 8 * 1024 * 1024;
const info = Object.fromEntries($('List All Messages').all().map(i => [i.json.id, i.json]));
const tooLarge = messages
  .filter(m => !emlFiles[m.id] && (info[m.id].sizeEstimate || 0) > MAX_BYTES)
  .map(m => ({ file_name: `${m.id}.eml`, size_mb: +(info[m.id].sizeEstimate / 1048576).toFixed(1),
               subject: info[m.id].Subject || '', from: info[m.id].From || '',
               date: new Date(+info[m.id].internalDate).toISOString().slice(0, 10) }));
const noFile = messages.filter(m => !emlFiles[m.id] && (info[m.id].sizeEstimate || 0) <= MAX_BYTES).map(m => m.id);
if (noFile.length) {
  throw new Error(`Email backup incomplete: ${noFile.length} of ${messages.length} emails have no .eml file (e.g. ${noFile.slice(0, 3).join(', ')}). Snapshot not saved.`);
}
const snapshot = {
  taken_at: new Date().toISOString(),
  email_backup_folder_id: folderId,
  // message id -> Drive file id of its .eml: a restore re-imports deleted emails from these
  eml_files: Object.fromEntries(messages.filter(m => emlFiles[m.id]).map(m => [m.id, emlFiles[m.id]])),
  // over 8 MB and not yet dropped into gmail-backup by hand
  too_large: tooLarge,
  label_names: labelNames,
  scope: c.scope,
  mailbox_total: $('Fetch Mailbox Size').first().json.messagesTotal,
  count: messages.length,
  messages,
};
const fileName = `gmail-labels-${snapshot.taken_at.replace(/[:.]/g, '-')}.json`;
return [{
  json: { fileName, count: messages.length },
  binary: { data: {
    data: Buffer.from(JSON.stringify(snapshot)).toString('base64'),
    mimeType: 'application/json',
    fileName,
  } },
}];

// Snapshot (as read back from Drive) vs the mailbox right now.
// backup:   proves the saved file is complete and readable. Throws if not.
// verify:   reports what changed since the snapshot. Changes nothing.
const c = $('Config').first().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const snap = JSON.parse(buf.toString('utf8'));

// Gmail sets these itself. They can't be added or removed.
const FIXED = new Set(['SENT', 'DRAFT', 'CHAT']);

const labelsOf = j => j.labelIds ?? (j.labels || []).map(l => l.id);
const now = new Map($('List All Messages').all().map(i => [i.json.id, labelsOf(i.json)]));
const changed = [], missing = [];
// A draft that is gone was sent, edited or discarded (a draft gets a new id on every edit).
// That is not a deleted email, so it does not count as missing.
let draftsGone = 0;
for (const m of snap.messages) {
  const cur = now.get(m.id);
  if (!cur) { if (m.labelIds.includes('DRAFT')) draftsGone++; else missing.push(m.id); continue; }
  const add = m.labelIds.filter(l => !cur.includes(l) && !FIXED.has(l));
  const remove = cur.filter(l => !m.labelIds.includes(l) && !FIXED.has(l));
  if (add.length || remove.length) changed.push({ id: m.id, add, remove });
}
const inSnapshot = new Set(snap.messages.map(m => m.id));
const newSince = [...now.keys()].filter(id => !inSnapshot.has(id)).length;

// The file this run read: the one just saved, or the one named in Config
const fileId = c.action === 'backup'
  ? $('Save Snapshot to Drive').first().json.id
  : (String(c.snapshot_file_id).match(/[-\w]{25,}/) || [''])[0];

const report = {
  action: c.action,
  snapshot_file_id: fileId,         // paste this into the restore form, or into snapshot_file_id for verify
  snapshot_link: `https://drive.google.com/file/d/${fileId}/view`,
  snapshot_taken_at: snap.taken_at,
  snapshot_count: snap.count,
  mailbox_total_at_snapshot: snap.mailbox_total,
  current_count: now.size,
  in_sync: changed.length === 0 && missing.length === 0,
  changed: changed.length,
  missing: missing.length,          // deleted for good: labels can't bring these back
  new_since_snapshot: newSince,     // arrived later: restore leaves them alone
  drafts_gone: draftsGone,          // drafts sent, edited or discarded since: restore skips them
  examples: changed.slice(0, 10),
  // Full content: every email in the snapshot has a .eml file (checked before the snapshot was saved)
  emails_backed_up: Object.keys(snap.eml_files || {}).length,
  // download these in Gmail (Download message), save into gmail-backup under file_name, run backup again
  emails_too_large: snap.too_large || [],
  email_backup_folder_id: snap.email_backup_folder_id || 'none: this snapshot holds labels only',
};

// backup: the snapshot just written must be complete, or nothing proceeds
if (c.action === 'backup') {
  const problems = [];
  if (snap.messages.length !== snap.count) problems.push(`file holds ${snap.messages.length} of ${snap.count} messages`);
  // Only a whole-mailbox snapshot can be checked against Gmail's own count,
  // which leaves out trash and spam
  const counted = snap.messages.filter(m => !m.labelIds.includes('TRASH') && !m.labelIds.includes('SPAM')).length;
  if (!snap.scope && counted < snap.mailbox_total) problems.push(`listed ${counted} of the ${snap.mailbox_total} messages Gmail reports (trash and spam excluded)`);
  if (report.emails_backed_up + report.emails_too_large.length !== snap.count) problems.push(`only ${report.emails_backed_up} of ${snap.count} emails have a .eml file`);
  if (!report.in_sync) problems.push(`file differs from the mailbox (${changed.length} changed, ${missing.length} missing)`);
  if (problems.length) throw new Error('Backup NOT verified: ' + problems.join('; '));
  report.verified = true;
}
return [{ json: report }];

// One item per email: label resets, then deleted emails to import back
const plan = $('Compute Restore Plan').first().json;
return [
  ...plan.changes.map(c => ({ json: c })),
  ...plan.reimports.map(r => ({ json: { ...r, reimport: true } })),
];

// What a restore would do, for the emails in the snapshot only. Emails that arrived later are never touched.
// - email still there, labels differ: reset the workflow's labels
// - email gone: re-import it from its .eml backup, with the labels it had
const snap = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'));

// n8n's Gmail node returns labels as [{id, name}], the raw API as labelIds. Accept both.
const labelsOf = j => j.labelIds ?? (j.labels || []).map(l => l.id);
// Gmail sets these itself. They can't be added or removed.
const FIXED = new Set(['SENT', 'DRAFT', 'CHAT']);

// Restore resets ONLY these labels, by name: by default the ones the inbox attachment organizer sets.
// Your own reading, starring and archiving is never undone.
// Add 'INBOX' once a workflow archives emails. An empty list restores every label.
const RESTORE_LABELS = ['n8n', 'gdr', 'inProgress'];

const idOf = {};
for (const i of $('List Current Labels').all()) for (const l of i.json.labels || []) idOf[l.name] = l.id;
for (const [id, name] of Object.entries(snap.label_names || {})) idOf[name] ??= id;
const scope = RESTORE_LABELS.length ? new Set(RESTORE_LABELS.map(n => idOf[n] ?? n)) : null;
const restorable = l => !FIXED.has(l) && (!scope || scope.has(l));

const now = new Map($('List Current Labels').all().map(i => [i.json.id, labelsOf(i.json)]));
if (now.size && [...now.values()].every(l => l.length === 0)) {
  throw new Error('No labels found on any current message: the label field was not read. Nothing restored.');
}
const changes = [], missing = [], reimport = [];
// A draft that is gone was sent, edited or discarded: Gmail gives a draft a new id on every
// edit. Importing it back would leave a stray copy next to the sent email.
let draftsGone = 0;
for (const m of snap.messages) {
  const cur = now.get(m.id);
  if (!cur) {
    if (m.labelIds.includes('DRAFT')) { draftsGone++; continue; }
    const fileId = (snap.eml_files || {})[m.id];
    if (fileId) reimport.push({ snapshot_id: m.id, file_id: fileId, labels: m.labelIds.filter(l => !FIXED.has(l)) });
    else missing.push(m.id);
    continue;
  }
  const add = m.labelIds.filter(l => !cur.includes(l) && restorable(l));
  const remove = cur.filter(l => !m.labelIds.includes(l) && restorable(l));
  if (add.length || remove.length) changes.push({ id: m.id, add, remove });
}
const inSnapshot = new Set(snap.messages.map(m => m.id));
return [{ json: {
  snapshot_taken_at: snap.taken_at,
  restoring_labels: RESTORE_LABELS.length ? RESTORE_LABELS.join(', ') : 'all labels',
  changed: changes.length,
  reimport: reimport.length,
  missing: missing.length,          // deleted, and this snapshot has no .eml for them
  drafts_gone: draftsGone,          // sent, edited or discarded since: not restored
  total: changes.length + reimport.length,
  new_since_snapshot: [...now.keys()].filter(id => !inSnapshot.has(id)).length,
  changes,
  reimports: reimport,
} }];

// Emails never change in Gmail, so each one is saved once, as <message id>.eml.
// Only emails without a file yet go on; the rest are already backed up.
const saved = new Set($('List Saved Emails').all().map(i => i.json.name).filter(Boolean));
// Emails over 8 MB hang the worker (a 21 MB one did, twice). They are listed in the result
// instead; download them in Gmail (Download message) and drop them here as <id>.eml.
const MAX_BYTES = 8 * 1024 * 1024;
const todo = $('List All Messages').all()
  .filter(i => (i.json.sizeEstimate || 0) <= MAX_BYTES)
  .map(i => i.json.id)
  .filter(id => !saved.has(`${id}.eml`));
// One item even when nothing is new, so the run always reaches Build Snapshot File
return todo.length ? todo.map(id => ({ json: { id } })) : [{ json: { nothing_new: true } }];

// The imported email has a new id. Give it the labels it had in the snapshot,
// and drop any Gmail added on import that it did not have.
const work = $('Download Email from Backup').all();
return $input.all().map((i, n) => {
  const want = work[n].json.labels;
  const got = i.json.labelIds || [];
  return { json: {
    id: i.json.id,
    add: want.filter(l => !got.includes(l)),
    remove: got.filter(l => !want.includes(l) && !['SENT', 'DRAFT', 'CHAT'].includes(l)),
  } };
});

// 25 emails per chunk. Each chunk is saved by a run of its own (When Saving Email Chunk),
// so this run never holds the raw mailbox in memory.
const SIZE = 25;
const ids = $input.all().map(i => i.json.id);
const folderId = $('Create Email Backup Folder').isExecuted ? $('Create Email Backup Folder').first().json.id : $('Find Email Backup Folder').first().json.id;
const chunks = [];
for (let i = 0; i < ids.length; i += SIZE) chunks.push({ json: { ids: ids.slice(i, i + SIZE), folder_id: folderId } });
return chunks;

// One item per email id of this chunk
const { ids, folder_id } = $input.first().json;
return ids.map(id => ({ json: { id, folder_id } }));
